<script setup lang="ts">
import { computed } from 'vue';
const props=defineProps<{ status:string; timestamps?:Record<string,string|null|undefined> }>();
const steps=[{key:'pending',label:'Order placed',date:'placed_at'},{key:'confirmed',label:'Confirmed',date:'confirmed_at'},{key:'shipped',label:'Sent to Kisaku store',date:'shipped_at'},{key:'received',label:'Received by Kisaku',date:'received_at'}];
const rank=computed(()=>props.status==='cancelled'?-1:steps.findIndex(s=>s.key===props.status));
function format(value?:string|null){if(!value)return '';const d=new Date(value);return Number.isNaN(d.getTime())?'':d.toLocaleString('en-KE',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}
</script><template><ol class="progress"><li v-for="(step,index) in steps" :key="step.key" :class="{done:index<=rank,active:index===rank}"><span class="dot">{{index+1}}</span><strong>{{step.label}}</strong><small v-if="timestamps?.[step.date]">{{format(timestamps[step.date])}}</small></li></ol></template><style scoped>.progress{display:grid;grid-template-columns:repeat(4,1fr);list-style:none;padding:0;margin:0}.progress li{position:relative;display:flex;flex-direction:column;align-items:center;text-align:center;color:#94a3b8;font-size:.72rem}.progress li:not(:last-child)::after{content:'';position:absolute;top:14px;left:calc(50% + 16px);width:calc(100% - 32px);height:3px;background:#e2e8f0}.progress li.done:not(:last-child)::after{background:#ff7900}.dot{z-index:1;width:29px;height:29px;margin-bottom:7px;border-radius:50%;display:grid;place-items:center;border:2px solid #cbd5e1;background:#fff;font-weight:800}.done .dot{border-color:#ff7900;background:#ff7900;color:#fff}.active strong{color:#075397}.progress strong{min-height:30px}.progress small{color:#64748b}@media(max-width:600px){.progress strong{font-size:.66rem}.progress{gap:2px}}</style>